// TH16 v1.00a Extra stage (st07) midstage wave: MainSub06 "GirlA04 six-batch queue".
// Source: st07.ecl.txt:1292-1356, deps GirlA04 326-335, GirlA04_at 337-354, GirlA04_at2 356-381.
// Source/card correspondence is noted next to each block below.

const TIME_LIMIT: int = 1924;
const OPENING_BUFFER: int = 120;

// etSprite(0, 8, 6): TH16 type 8 rice, color 6 (bullet-types.md, approved TH16 aliases).
const TH16_RICE: int = 480;

// Source GirlA04_at2 EX: VELTIME(a=60, r=1.0) runs as a 60-frame persistent effect on the
// bullet; the following LASER record then replaces the bullet with a line laser.
// Target: bullet expires after 60 frames (set_life(1) on the 60th frame's transform phase,
// which runs after the ECL tasks, so the conversion task below still sees the bullet).
xformdef BULLET_EXPIRE_60 {
    wait(60);
    set_life(1);
}

// Source EX LASER (etExSet2 index 3, a=0 line) + paired SHOOT_DATA (index 4):
// sprite 8 / color 6, s=4 speed, m=32 length, paired s2=16 width, r angle sentinel
// (-999999 -> keep the parent bullet angle), d=1 -> delete parent.
// Line judgment segment with flags 0x2 clear = [0.1L, 0.9L] -> [3.2, 28.8]; width w=16<32
// gives half-height w/4=4 -> target width 8 (lasers.md). The line translates at 4 px/frame,
// so its segment at travel T is [3.2+T, 28.8+T]; lz_speed grows the rod from its origin and
// then keeps [end-25.6, end], so the origin is placed 0.9L ahead of the bullet to make the
// full-length phase line up exactly (the first ~7 frames are a shorter growth ramp).
async sub bullet_to_laser() {
    wait(59);                       // bullet task starts one frame after spawn
    var a: angle = $self_angle;     // source r sentinel keeps the bullet angle
    var ox: fx = $self_x + 28.8fx * cos(a);
    var oy: fx = $self_y + 28.8fx * sin(a);
    var h: int = laser(6, ox, oy, a, 25.6fx, 8fx, 0, 9999, 0);
    lz_speed(h, 4fx, 25.6fx);       // source line speed 4, rod length 0.8L
}

// Source GirlA04_at2: wait(10 + RAND%40), then etNew(0)/etAim(0,1)/etSprite(0,8,6)/
// etCount(0,1,1)/etAngle(0,0,0)/etSpeed(0,1.0,0.2); 80 shots, one every 60 frames,
// each aimed at the player with a signed +-1 * 0.05235988 rad (RANDF2) jitter.
async sub girl_fire() {
    wait(10 + rand(40));
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 6);
    sh_aim(0, 1);                   // source etAim(0,1) base = player angle
    sh_ring(0, 0);                  // fan; count 1 so the 0.5235988 spread has no effect
    sh_count(0, 1, 1);
    sh_speed(0, 1fx, 0fx);          // etSpeed(0,1.0,0.2), M=1 -> s0
    sh_angle(0, 0deg, 0deg);
    sh_xform(0, BULLET_EXPIRE_60);
    sh_task(0, bullet_to_laser);
    for i in 0..80 {
        var r: int = rand(65536) - 32768;
        var off: angle = (r * 546 / 32768) as angle;   // +-3 deg = +-546 BAM
        sh_angle(0, off, 0deg);     // ANGLE_PLAYER + RANDF2 * 0.05235988
        sh_fire(0);
        wait(60);
    }
}

// Source GirlA04 (anmSelect/anmSetMain/drops omitted as presentation/reward) ->
// GirlA04_at: setHurtbox(24,24)->r12, setHitbox(16,16)->r8, dropSeason omitted,
// @GirlA04_at2 async, then REL ellipse r=32 omega=0.034906585 (2 deg/frame) with phase F0,
// ABS moveVel(up,0.3) and moveVelTime(120,mode1,..,1.0) then moveVelTime(60,mode4,..,0.5),
// then an idle loop. ABS and REL are composed per frame; source sets the orbit position
// immediately at the setter frame (circular-motion.md).
async sub girl(phase: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_fire();
    var x: fx = $self_x;
    var y: fx = 480fx;
    var theta: angle = phase;
    move_to(0, x + 32fx * cos(theta), y + 32fx * sin(theta), EASE_LINEAR);
    for k1 in 1..121 {
        wait(1);
        var t: fx = k1 as fx / 120fx;
        y = y - 0.3fx - 0.7fx * t * t;          // mode1 (t^2) 0.3 -> 1.0 over 120 frames
        theta = theta + 364bam;                 // 0.034906585 rad/frame
        move_to(0, x + 32fx * cos(theta), y + 32fx * sin(theta), EASE_LINEAR);
    }
    for k2 in 1..61 {
        wait(1);
        var u: fx = 1fx - k2 as fx / 60fx;
        y = y - 0.5fx - 0.5fx * u * u;          // mode4 (1-(1-t)^2) 1.0 -> 0.5 over 60 frames
        theta = theta + 364bam;
        move_to(0, x + 32fx * cos(theta), y + 32fx * sin(theta), EASE_LINEAR);
    }
    loop {
        wait(1);
        y = y - 0.5fx;
        theta = theta + 364bam;
        move_to(0, x + 32fx * cos(theta), y + 32fx * sin(theta), EASE_LINEAR);
    }
}

// MainSub06 batch: enmCreate relative to the stage (0,0), x = A-192 with A = 32,64,..
sub spawn_wave(phase: angle) {
    for i in 0..12 {
        _ = spawn_enemy((-160 + i * 32) as fx, 480fx, 220, 0, 1000, 0, girl(phase));
    }
}

// MainSub06 schedule: six batches of 12, F0 = 0, pi, 0, pi, 0, pi/2.
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_wave(0deg);
    wait(100);
    spawn_wave(180deg);
    wait(100);
    spawn_wave(0deg);
    wait(300);
    spawn_wave(180deg);
    wait(100);
    spawn_wave(0deg);
    wait(100);
    spawn_wave(90deg);
    wait(300);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
